#!/usr/bin/env python3
"""Write REVIEW-CHECKLIST.md: every reference a scholar must verify and every disputed statement, by stage."""
import glob, json
from collections import Counter
from pathlib import Path
HERE = Path(__file__).resolve().parents[1]
acts = sorted((json.load(open(f, encoding="utf-8")) for f in glob.glob(str(HERE / "acts/act*.json"))), key=lambda a: a["act"])
refs, out = Counter(), ["# Review checklist: Hijrah Night v2", "",
       "Generated by tools/review_checklist.py. Tick each item when a scholar has checked the wording, numbering and grade.", ""]
def stmts(u):
    for s in u.get("statements", []): yield s
    for d in u.get("discover", []):
        if d.get("reveal"): yield d["reveal"]
for a in acts:
    out += [f"## Act {a['act']}: {a['title']}", ""]
    for u in a["units"]:
        items = []
        for s in stmts(u):
            for x in s.get("sources", []):
                if x.get("type") in ("hadith", "other"):
                    refs[x["ref"]] += 1
                    items.append(f"- [ ] verify **{x['ref']}**{' (' + x['grade'] + ')' if x.get('grade') else ''}: “{s['text'][:140]}…”")
            if s["grade"] == "disputed":
                items.append(f"- [ ] disputed: “{s['text'][:140]}…” — {s.get('note') or '; '.join(x.get('note','') for x in s.get('sources', []))}")
        for q in u.get("quran", []):
            items.append(f"- [ ] Qurʾān {q['ref']}: gist and link to this moment")
        if items:
            out += [f"### {u['id']} · {u['title']}", *items, ""]
out += ["## Most-cited outside references", ""] + [f"- {r}: {n}" for r, n in refs.most_common(30)]
(HERE / "REVIEW-CHECKLIST.md").write_text("\n".join(out) + "\n", encoding="utf-8")
print(f"{sum(1 for l in out if l.startswith('- [ ]'))} items")
